        [Test]
        public void Test_IsSafeInteger()
        {
            foreach (var value in new long[]
            {
                0L, 9007199254740991L, -9007199254740991L
            })
            {
                Assert.IsTrue(Our.Common.IsSafeInteger(value), $"for {value}");
            }

            foreach (var value in new long[]
            {
                9007199254740992L, -9007199254740992L, long.MaxValue, long.MinValue
            })
            {
                Assert.IsFalse(Our.Common.IsSafeInteger(value), $"for {value}");
            }

            Assert.IsTrue(Our.Common.IsSafeInteger(9007199254740991UL));
            Assert.IsFalse(Our.Common.IsSafeInteger(9007199254740992UL));
            Assert.IsFalse(Our.Common.IsSafeInteger(ulong.MaxValue));

            foreach (var value in new double[]
            {
                0.0, 9007199254740991.0, -9007199254740991.0
            })
            {
                Assert.IsTrue(Our.Common.IsSafeInteger(value), $"for {value}");
            }

            foreach (var value in new double[]
            {
                9007199254740992.0,
                -9007199254740992.0,
                double.PositiveInfinity,
                double.NegativeInfinity,
                double.NaN
            })
            {
                Assert.IsFalse(Our.Common.IsSafeInteger(value), $"for {value}");
            }
        }  // public void Test_IsSafeInteger

