        [Test]
        public void Test_JsonValueFrom_checks_the_safe_integer_range()
        {
            foreach (var value in new long[] { 9007199254740992L, -9007199254740992L })
            {
                var exception = Assert.Throws<Our.Jsonization.Exception>(
                    () => Our.Jsonization.Deserialize.JsonValueFrom(
                        new Nodes.JsonArray(Nodes.JsonValue.Create(value))));
                Assert.AreEqual(
                    $"Expected a JSON-able value, but got the integer {value}, " +
                    "which is outside the safe integer range [-2^53 + 1, 2^53 - 1]",
                    exception!.Cause);
                Assert.AreEqual("[0]", exception!.Path);
            }

            foreach (var value in new long[] { 9007199254740991L, -9007199254740991L })
            {
                Assert.DoesNotThrow(
                    () => Our.Jsonization.Deserialize.JsonValueFrom(
                        new Nodes.JsonArray(Nodes.JsonValue.Create(value))));
